private void pop(final String descriptor) {
    int slots = 0;
    int i = 0;
    if (descriptor.length() == 0) {
        return;
    }
    if (descriptor.charAt(0) == '(') {
        // method descriptor: parse argument types
        i++; // skip '('
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == '[') {
                // array type: skip all '['
                while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                    i++;
                }
                // component type
                if (i < descriptor.length()) {
                    c = descriptor.charAt(i);
                    if (c == 'L') {
                        // object type
                        i++; // skip 'L'
                        while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                            i++;
                        }
                        if (i < descriptor.length()) {
                            i++; // skip ';'
                        }
                    } else {
                        // primitive component
                        i++;
                    }
                }
                slots += 1;
            } else if (c == 'L') {
                // object type
                i++; // skip 'L'
                while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i < descriptor.length()) {
                    i++; // skip ';'
                }
                slots += 1;
            } else {
                // primitive type
                if (c == 'J' || c == 'D') {
                    slots += 2;
                } else if (c != 'V') {
                    slots += 1;
                }
                i++;
            }
        }
        // skip ')'
        if (i < descriptor.length() && descriptor.charAt(i) == ')') {
            i++;
        }
        // skip return type (ignored)
    } else {
        // single type descriptor
        char c = descriptor.charAt(i);
        if (c == '[') {
            while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i < descriptor.length()) {
                c = descriptor.charAt(i);
                if (c == 'L') {
                    i++; // skip 'L'
                    while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                        i++;
