        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node must not be null");
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // If the starting node already satisfies the predicate or is the stop node, return immediately.
    if (predicate.test(circ.node()) || circ.node().equals(stop)) {
        return circ;
    }

    // Traverse until we hit the stop node or find a node that satisfies the predicate.
    while (!circ.node().equals(stop) && !predicate.test(circ.node())) {
        circ.next();
    }

    return circ;
}

