private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true; // a single vertex or empty set is trivially a clique
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2)) {
                try {
                    if (graph.getEdge(v1, v2) == null) {
                        return false;
                    }
                } catch (Exception e) {
                    // If the graph implementation throws an exception for missing vertices
                    return false;
                }
            }
        }
    }
    return true;
}

