public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pType = (ParameterizedType) genericType;
    Type[] args = pType.getActualTypeArguments();
    if (args == null || args.length == 0) {
        return null;
    }
    // Build a map of type variables to actual types for the target type hierarchy
    Map<TypeVariable<?>, Type> typeVarMap = new HashMap<>();
    Class<?> current = targetType;
    while (current != null) {
        // Superclass
        Type genericSuper = current.getGenericSuperclass();
        if (genericSuper instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) genericSuper;
            Class<?> superClass = (Class<?>) pt.getRawType();
            TypeVariable<?>[] vars = superClass.getTypeParameters();
            Type[] argsSuper = pt.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                Type arg = argsSuper[i];
                if (arg instanceof TypeVariable && typeVarMap.containsKey(arg)) {
                    arg = typeVarMap.get(arg);
                }
                typeVarMap.put(vars[i], arg);
            }
        }
        // Interfaces
        Type[] genericInterfaces = current.getGenericInterfaces();
        for (Type gi : genericInterfaces) {
            if (gi instanceof ParameterizedType) {
                ParameterizedType pt = (ParameterizedType) gi;
                Class<?> iface = (Class<?>) pt.getRawType();
                TypeVariable<?>[] vars = iface.getTypeParameters();
                Type[] argsIface = pt.getActualTypeArguments();
                for (int i = 0; i < vars.length; i++) {
                    Type arg = argsIface[i];
                    if (arg instanceof TypeVariable && typeVarMap.containsKey(arg)) {
                        arg = typeVarMap.get(arg);
                    }
                    typeVarMap.put(vars[i], arg);
                }
            }
        }
        current = current.getSuperclass();
    }

    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Type arg = args[i];
        Class<?> resolved = null;
        if (arg instanceof Class<?>) {
            resolved = (Class<?>) arg;
        } else if (arg instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) arg).getRawType();
            if (raw instanceof Class<?>) {
                resolved = (Class<?>) raw;
            }
        } else if (arg instanceof TypeVariable<?>) {
            Type mapped = typeVarMap.get(arg);
            if (mapped == null) {
                return null;
            }
            if (mapped instanceof Class<?>) {
                resolved = (Class<?>) mapped;
            } else if (mapped instanceof ParameterizedType) {
                Type raw = ((ParameterizedType) mapped).getRawType();
                if (raw instanceof Class<?>) {
                    resolved = (Class<?>) raw;
                }
            }
        } else if (arg instanceof GenericArrayType) {
            // Attempt to resolve component type
            Type comp = ((GenericArrayType) arg).getGenericComponentType();
            if (comp instanceof Class<?>) {
                resolved = Array.newInstance((Class<?>) comp, 0).getClass();
            } else if (comp instanceof ParameterizedType) {
                Type raw = ((ParameterizedType) comp).getRawType();
                if (raw instanceof Class<?>) {
                    resolved = Array.newInstance((Class<?>) raw, 0).getClass();
                }
            }
        }
        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }
    return result;
