protected int removeUnusedNodes() {
    int removedCount = 0;
    try {
        // If the root itself is inactive, clear the entire tree
        if (root == null) {
            return 0;
        }
        if (!root.isActive()) {
            root = null;
            return 1;
        }

        // Use a stack for depth‑first traversal to avoid ConcurrentModificationException
        Deque<Category> stack = new ArrayDeque<>();
        stack.push(root);

        while (!stack.isEmpty()) {
            Category current = stack.pop();
            List<Category> children = current.getChildren();
            if (children == null) {
                continue;
            }

            Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                if (child == null) {
                    continue;
                }
                if (!child.isActive()) {
                    // Remove inactive child and count it
                    it.remove();
                    removedCount++;
                } else {
                    // Continue traversal on active child
                    stack.push(child);
                }
            }
        }
    } catch (Exception e) {
        // Log or rethrow as needed; for now, just return the count so far
        // e.printStackTrace(); // Uncomment if debugging is required
    }
    return removedCount;
}

