protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long current = start;
    while (current < end) {
        long remaining = end - current;
        long chunkSize = remaining <= FETCH_DATA_DURATION ? remaining : FETCH_DATA_DURATION;
        long chunkEnd = current + chunkSize;
        ranges.add(new TimeRange(current, chunkEnd));
        current = chunkEnd;
    }
    return ranges;
}

