public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("desiredCapacity must be non-negative");
    }
    if (desiredCapacity < 2) {
        return 2;
    }
    int maxCapacity = desiredCapacity;
    if (desiredCapacity >= 1000) {
        maxCapacity = (int) Math.floor(desiredCapacity * 1.11);
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        if (candidate == 2) {
            return 2;
        }
        candidate++;
    }
    while (candidate <= maxCapacity) {
        boolean prime = true;
        for (int i = 2; i * i <= candidate; i++) {
            if (candidate % i == 0) {
                prime = false;
                break;
            }
        }
        if (prime) {
            return candidate;
        }
        candidate += 2;
