public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream is null");
    }
    if (message == null) {
        throw new NullPointerException("Message is null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema is null");
    }
    if (buffer == null) {
        throw new NullPointerException("LinkedBuffer is null");
    }
    // Serialize the message into the buffer
    try {
        schema.writeTo(message, buffer);
    } catch (Exception e) {
        throw new IOException("Failed to serialize message", e);
    }
    int size = buffer.getSize();
    int originalSize = size;
    // Write the length prefix as a varint
    while (size > 0x7F) {
        out.write((size & 0x7F) | 0x80);
        size >>>= 7;
    }
    out.write(size);
    // Write the serialized bytes
    out.write(buffer.getBuffer(), 0, originalSize);
    return originalSize;
}

