public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        return 0;
    }
    final int strLen = str.length();
    if (index < 0 || len < 0 || index > strLen || index + len > strLen) {
        throw new IndexOutOfBoundsException("index and len out of bounds");
    }
    int end = index + len;
    int size = 0;
    for (int i = index; i < end; ) {
        int cp = Character.codePointAt(str, i);
        int bytes;
        if (cp <= 0x7F) {
            bytes = 1;
        } else if (cp <= 0x7FF) {
            bytes = 2;
        } else if (cp <= 0xFFFF) {
            bytes = 3;
        } else {
            bytes = 4;
        }
        size += bytes;
        i += Character.charCount(cp);
    }
    return size;
}

