public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new NullPointerException("DataOutput is null");
    }
    int totalSize = 0;
    while (node != null) {
        byte[] buf = node.buf;
        int start = node.start;
        int end = node.end;
        if (buf != null && end > start) {
            out.write(buf, start, end - start);
            totalSize += end - start;
        }
        node = node.next;
    }
    return totalSize;
}

